def simulate(config):
    steps = 0
    current = list(config)
    while True:
        k = sum(current)
        if k == 0:
            break
        current[k-1] = 1 - current[k-1]
        steps += 1
    return steps

def solve(n):
    total_steps = 0
    for i in range(2**n):
        config = []
        for j in range(n):
            config.append((i >> j) & 1)
        total_steps += simulate(config)
    return total_steps / (2**n)

for n in range(1, 8):
    print(f"n={n}, avg={solve(n)}")

